<?php
if(!defined('SCHOOLOS_SERVICES_LIBRARY')){header('Location: index.php?s=services&area=inventory');exit;}
function iv_schema():array{return [
 "CREATE TABLE IF NOT EXISTS iv_items(tenant_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,price_kobo BIGINT NOT NULL DEFAULT 0,cost_kobo BIGINT NOT NULL DEFAULT 0,store_active TINYINT NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_moves(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,delta INT NOT NULL,kind VARCHAR(20) NOT NULL,recipient VARCHAR(190) NOT NULL,note VARCHAR(1000) NOT NULL,event_key VARCHAR(100) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY once_move(tenant_id,event_key),INDEX(tenant_id,item_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_suppliers(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,email VARCHAR(190) NOT NULL,phone VARCHAR(40) NOT NULL,address VARCHAR(500) NOT NULL,active TINYINT NOT NULL DEFAULT 1) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_requests(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_kobo BIGINT NOT NULL,reason TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending',requested_by BIGINT UNSIGNED NOT NULL,reviewed_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(tenant_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,supplier_id BIGINT UNSIGNED NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'draft',created_by BIGINT UNSIGNED NOT NULL,approved_by BIGINT UNSIGNED NULL,payment_ref VARCHAR(120) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_order_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,order_id BIGINT UNSIGNED NOT NULL,request_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_kobo BIGINT NOT NULL,received INT NOT NULL DEFAULT 0,UNIQUE KEY request_once(tenant_id,request_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,line_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,reference VARCHAR(100) NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY receipt_once(tenant_id,reference)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_store_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,student_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,quantity INT NOT NULL,unit_kobo BIGINT NOT NULL,status VARCHAR(24) NOT NULL DEFAULT 'requested',invoice_id BIGINT UNSIGNED NULL,requested_by BIGINT UNSIGNED NOT NULL,handled_by BIGINT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_asset_meta(tenant_id BIGINT UNSIGNED NOT NULL,asset_id BIGINT UNSIGNED NOT NULL,tag VARCHAR(80) NOT NULL,cost_kobo BIGINT NOT NULL,residual_kobo BIGINT NOT NULL,life_months INT NOT NULL,purchased_on DATE NOT NULL,depreciated_kobo BIGINT NOT NULL DEFAULT 0,last_period VARCHAR(7) NULL,status VARCHAR(20) NOT NULL DEFAULT 'active',PRIMARY KEY(tenant_id,asset_id),UNIQUE KEY asset_tag(tenant_id,tag)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_asset_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,asset_id BIGINT UNSIGNED NOT NULL,kind VARCHAR(20) NOT NULL,title VARCHAR(180) NOT NULL,body TEXT NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'open',amount_kobo BIGINT NOT NULL DEFAULT 0,period VARCHAR(7) NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY dep_once(tenant_id,asset_id,kind,period)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4",
 "CREATE TABLE IF NOT EXISTS iv_audits(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,tenant_id BIGINT UNSIGNED NOT NULL,item_id BIGINT UNSIGNED NOT NULL,expected INT NOT NULL,observed INT NOT NULL,note TEXT NOT NULL,created_by BIGINT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4"
];}
function iv_move(array $u,array $item,int $delta,string $kind,string $recipient,string $note,string $key):void{$old=q('SELECT * FROM iv_moves WHERE tenant_id=? AND event_key=?',[$u['tenant_id'],$key])->fetch();if($old){if((int)$old['item_id']!==(int)$item['id']||(int)$old['delta']!==$delta||$old['kind']!==$kind)throw new RuntimeException('Reference was already used for a different movement.');return;}if((int)$item['quantity']+$delta<0||(int)$item['quantity']+$delta>100000000)throw new RuntimeException('Stock cannot be negative or exceed supported capacity.');q('INSERT INTO iv_moves(tenant_id,item_id,delta,kind,recipient,note,event_key,created_by) VALUES(?,?,?,?,?,?,?,?)',[$u['tenant_id'],$item['id'],$delta,$kind,$recipient,$note,$key,$u['id']]);q('UPDATE inventory SET quantity=quantity+? WHERE tenant_id=? AND id=?',[$delta,$u['tenant_id'],$item['id']]);}
function iv_depreciation(array $m,string $period):int{if(!preg_match('/^\d{4}-(0[1-9]|1[0-2])$/D',$period))throw new RuntimeException('Use YYYY-MM.');$start=substr($m['purchased_on'],0,7);if($period<$start||$period>date('Y-m'))throw new RuntimeException('Choose a period since purchase and no later than this month.');$months=((int)substr($period,0,4)-(int)substr($start,0,4))*12+(int)substr($period,5,2)-(int)substr($start,5,2)+1;$months=min((int)$m['life_months'],$months);return intdiv(((int)$m['cost_kobo']-(int)$m['residual_kobo'])*$months,(int)$m['life_months']);}
function iv_action(array $u,string $a):string{
 global $pdo;$tid=(int)$u['tenant_id'];$uid=(int)$u['id'];$stock=sv_can($u,'stock_manager');
 if($a==='request'){if(!in_array($u['role'],['staff','teacher','school_admin'],true))throw new RuntimeException('Employee account required.');sv_own('inventory',$u,op_id('item_id'));q('INSERT INTO iv_requests(tenant_id,item_id,quantity,unit_kobo,reason,requested_by) VALUES(?,?,?,?,?,?)',[$tid,op_id('item_id'),sv_qty('quantity'),op_money(op_text('unit_cost',20,true)),op_text('reason',2000,true),$uid]);return 'Purchase request submitted for independent approval.';}
 if($a==='store_request'){$sid=op_id('student_id');sv_student($u,$sid,'stock_manager');return sv_tx(function()use($u,$tid,$uid,$sid){$item=sv_own('inventory',$u,op_id('item_id'),true);$m=q('SELECT * FROM iv_items WHERE tenant_id=? AND item_id=?',[$tid,$item['id']])->fetch();$qty=sv_qty('quantity',1000);if(!$m||!$m['store_active']||(int)$m['price_kobo']<1||(int)$item['quantity']<$qty)throw new RuntimeException('Store item, price or stock unavailable.');q('INSERT INTO iv_store_orders(tenant_id,student_id,item_id,quantity,unit_kobo,requested_by) VALUES(?,?,?,?,?,?)',[$tid,$sid,$item['id'],$qty,$m['price_kobo'],$uid]);return 'Store order requested. Stock is reserved only when school staff approve it.';});}
 if($a==='store_cancel'){return sv_tx(function()use($u,$tid,$stock){$o=sv_own('iv_store_orders',$u,op_id('order_id'),true);if(!$stock&&(int)$o['requested_by']!==(int)$u['id'])throw new RuntimeException('Order unavailable.');if($o['status']!=='requested')throw new RuntimeException('Only unapproved store requests can be cancelled. Review any invoiced order with Finance.');q("UPDATE iv_store_orders SET status='cancelled' WHERE tenant_id=? AND id=?",[$tid,$o['id']]);return 'Unapproved store request cancelled.';});}
 if($a==='review_request'){sv_need($u,'procurement_approver');return sv_tx(function()use($u,$tid,$uid){$r=sv_own('iv_requests',$u,op_id('request_id'),true);if($r['status']!=='pending'||(int)$r['requested_by']===$uid)throw new RuntimeException('A different reviewer must review a pending request.');$decision=sv_enum('status',['approved','rejected']);q('UPDATE iv_requests SET status=?,reviewed_by=? WHERE tenant_id=? AND id=?',[$decision,$uid,$tid,$r['id']]);return 'Purchase request reviewed.';});}
 if($a==='approve_order'){sv_need($u,'procurement_approver');return sv_tx(function()use($u,$tid,$uid){$o=sv_own('iv_orders',$u,op_id('order_id'),true);if($o['status']!=='submitted'||(int)$o['created_by']===$uid||!g('SELECT id FROM iv_order_lines WHERE tenant_id=? AND order_id=?',[$tid,$o['id']]))throw new RuntimeException('A different approver must review a submitted nonempty order.');if(g('SELECT l.id FROM iv_order_lines l JOIN iv_requests r ON r.id=l.request_id AND r.tenant_id=l.tenant_id WHERE l.tenant_id=? AND l.order_id=? AND r.requested_by=? LIMIT 1',[$tid,$o['id'],$uid]))throw new RuntimeException('An order containing your own request needs another approver.');q("UPDATE iv_orders SET status='approved',approved_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$o['id']]);return 'Purchase order independently approved.';});}
 if($a==='asset'||$a==='asset_event'||$a==='close_asset_event'||$a==='depreciate'){
  sv_need($u,'asset_manager');
  if($a==='asset'){return sv_tx(function()use($u,$tid){$id=op_id('asset_id');if($id)sv_own('assets',$u,$id,true);$cost=op_money(op_text('cost',20,true),true);$res=op_money(op_text('residual',20,true),true);if($res>$cost)throw new RuntimeException('Residual exceeds acquisition cost.');$date=op_date(op_text('purchased_on',10,true));if($date>date('Y-m-d'))throw new RuntimeException('Acquisition date cannot be in the future.');$life=sv_qty('life_months',1200);if($id&&g('SELECT asset_id FROM iv_asset_meta WHERE tenant_id=? AND asset_id=?',[$tid,$id]))throw new RuntimeException('Asset accounting setup is immutable. Use maintenance/audit records for subsequent changes.');if(!$id){q('INSERT INTO assets(tenant_id,name,serial_no,location,condition_status) VALUES(?,?,?,?,?)',[$tid,op_text('name',180,true),op_text('serial_no',120),op_text('location',120,true),op_text('condition_status',50,true)]);$id=(int)$GLOBALS['pdo']->lastInsertId();}q('INSERT INTO iv_asset_meta(tenant_id,asset_id,tag,cost_kobo,residual_kobo,life_months,purchased_on) VALUES(?,?,?,?,?,?,?)',[$tid,$id,op_text('tag',80,true),$cost,$res,$life,$date]);audit('asset.register','asset',(string)$id);return 'Asset registered; this does not duplicate an acquisition payment in Finance.';});}
  if($a==='asset_event'){$asset=sv_own('assets',$u,op_id('asset_id'));$kind=sv_enum('kind',['maintenance','audit']);q('INSERT INTO iv_asset_events(tenant_id,asset_id,kind,title,body,created_by) VALUES(?,?,?,?,?,?)',[$tid,$asset['id'],$kind,op_text('title',180,true),op_text('body',3000,true),$uid]);return 'Asset maintenance/audit record created.';}
  if($a==='close_asset_event'){$r=sv_own('iv_asset_events',$u,op_id('event_id'));if($r['kind']==='depreciation')throw new RuntimeException('Posted depreciation is immutable.');q("UPDATE iv_asset_events SET status='closed' WHERE tenant_id=? AND id=?",[$tid,$r['id']]);return 'Asset event closed.';}
  return sv_tx(function()use($u,$tid,$uid){$asset=sv_own('assets',$u,op_id('asset_id'),true);$m=q('SELECT * FROM iv_asset_meta WHERE tenant_id=? AND asset_id=? FOR UPDATE',[$tid,$asset['id']])->fetch();if(!$m)throw new RuntimeException('Configure asset accounting first.');$period=op_text('period',7,true);$target=iv_depreciation($m,$period);if($m['last_period']!==null&&$period<=$m['last_period'])throw new RuntimeException('Depreciation is already posted for this or a later period.');$amount=max(0,$target-(int)$m['depreciated_kobo']);q("INSERT INTO iv_asset_events(tenant_id,asset_id,kind,title,body,status,amount_kobo,period,created_by) VALUES(?,?,'depreciation',?,?,'posted',?,?,?)",[$tid,$asset['id'],'Straight-line '.$period,'Cumulative monthly depreciation, including acquisition month.',$amount,$period,$uid]);$event=(int)$GLOBALS['pdo']->lastInsertId();if($amount)fnJournal($tid,'ASSET-DEP-'.$event,'5200','1590',$amount,'','Asset #'.$asset['id'].' '.$period);q('UPDATE iv_asset_meta SET depreciated_kobo=?,last_period=? WHERE tenant_id=? AND asset_id=?',[$target,$period,$tid,$asset['id']]);return 'Depreciation posted once; residual value is protected.';});
 }
 sv_need($u,'stock_manager');
 if($a==='item'){return sv_tx(function()use($u,$tid){$id=op_id('item_id');if($id)sv_own('inventory',$u,$id,true);else{q('INSERT INTO inventory(tenant_id,name,category,quantity,reorder_level,unit_cost) VALUES(?,?,?,0,?,0)',[$tid,op_text('name',180,true),op_text('category',120,true),sv_qty('reorder_level',1000000,true)]);$id=(int)$GLOBALS['pdo']->lastInsertId();}q('UPDATE inventory SET name=?,category=?,reorder_level=? WHERE tenant_id=? AND id=?',[op_text('name',180,true),op_text('category',120,true),sv_qty('reorder_level',1000000,true),$tid,$id]);q('INSERT INTO iv_items(tenant_id,item_id,kind,price_kobo,cost_kobo,store_active) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE kind=VALUES(kind),price_kobo=VALUES(price_kobo),store_active=VALUES(store_active)',[$tid,$id,sv_enum('kind',['uniform','book','store','consumable']),op_money(op_text('price',20,true),true),op_money(op_text('cost',20,true),true),isset($_POST['store_active'])?1:0]);return 'Stock item configured; quantity and existing records retained.';});}
 if($a==='adjust'||$a==='issue'){return sv_tx(function()use($u,$tid,$a){$item=sv_own('inventory',$u,op_id('item_id'),true);if($a==='issue')$d=-sv_qty('quantity');else{$raw=op_text('delta',8,true);if(!preg_match('/^-?\d{1,6}$/D',$raw)||(int)$raw===0)throw new RuntimeException('Use a nonzero whole-unit adjustment.');$d=(int)$raw;}$key='MAN-'.op_text('reference',80,true);iv_move($u,$item,$d,$a,op_text('recipient',190,true),op_text('note',1000,true),$key);audit('stock.'.$a,'item',(string)$item['id']);return 'Stock movement saved once for this reference.';});}
 if($a==='supplier'){q('INSERT INTO iv_suppliers(tenant_id,name,email,phone,address) VALUES(?,?,?,?,?)',[$tid,op_text('name',180,true),op_text('email',190),op_text('phone',40,true),op_text('address',500,true)]);return 'Supplier registered.';}
 if($a==='order'){sv_own('iv_suppliers',$u,op_id('supplier_id'));q('INSERT INTO iv_orders(tenant_id,supplier_id,created_by) VALUES(?,?,?)',[$tid,op_id('supplier_id'),$uid]);return 'Draft purchase order created.';}
 if($a==='order_line'){return sv_tx(function()use($u,$tid){$o=sv_own('iv_orders',$u,op_id('order_id'),true);$r=sv_own('iv_requests',$u,op_id('request_id'),true);if($o['status']!=='draft'||$r['status']!=='approved')throw new RuntimeException('Choose a draft order and an approved request.');q('INSERT INTO iv_order_lines(tenant_id,order_id,request_id,item_id,quantity,unit_kobo) VALUES(?,?,?,?,?,?)',[$tid,$o['id'],$r['id'],$r['item_id'],$r['quantity'],$r['unit_kobo']]);return 'Approved request added to purchase order.';});}
 if($a==='submit_order'){return sv_tx(function()use($u,$tid){$o=sv_own('iv_orders',$u,op_id('order_id'),true);if($o['status']!=='draft'||!g('SELECT id FROM iv_order_lines WHERE tenant_id=? AND order_id=?',[$tid,$o['id']]))throw new RuntimeException('A nonempty draft order is required.');q("UPDATE iv_orders SET status='submitted' WHERE tenant_id=? AND id=?",[$tid,$o['id']]);return 'Order submitted for independent approval.';});}
 if($a==='receive'){return sv_tx(function()use($u,$tid,$uid){$pre=sv_own('iv_order_lines',$u,op_id('line_id'));$o=sv_own('iv_orders',$u,(int)$pre['order_id'],true);$line=sv_own('iv_order_lines',$u,(int)$pre['id'],true);$qty=sv_qty('quantity');$ref=op_text('reference',100,true);$old=q('SELECT * FROM iv_receipts WHERE tenant_id=? AND reference=?',[$tid,$ref])->fetch();if($old){if((int)$old['line_id']!==(int)$line['id']||(int)$old['quantity']!==$qty)throw new RuntimeException('Receipt reference differs from earlier receipt.');return 'Receipt already recorded; no stock or journal duplicated.';}if(!in_array($o['status'],['approved','partial'],true)||$qty>(int)$line['quantity']-(int)$line['received'])throw new RuntimeException('Order must be approved; received quantity cannot exceed the outstanding line.');$item=sv_own('inventory',$u,(int)$line['item_id'],true);q('INSERT INTO iv_receipts(tenant_id,line_id,quantity,reference,created_by) VALUES(?,?,?,?,?)',[$tid,$line['id'],$qty,$ref,$uid]);$receipt=(int)$GLOBALS['pdo']->lastInsertId();iv_move($u,$item,$qty,'receipt','School stock','PO #'.$o['id'],'PO-RECEIPT-'.$receipt);$meta=q('SELECT * FROM iv_items WHERE tenant_id=? AND item_id=?',[$tid,$item['id']])->fetch();if($meta){$total=(int)$item['quantity']*(int)$meta['cost_kobo']+$qty*(int)$line['unit_kobo'];$units=(int)$item['quantity']+$qty;q('UPDATE iv_items SET cost_kobo=? WHERE tenant_id=? AND item_id=?',[intdiv($total+intdiv($units,2),$units),$tid,$item['id']]);}q('UPDATE iv_order_lines SET received=received+? WHERE tenant_id=? AND id=?',[$qty,$tid,$line['id']]);if((int)$line['received']+$qty===(int)$line['quantity'])q("UPDATE iv_requests SET status='fulfilled' WHERE tenant_id=? AND id=?",[$tid,$line['request_id']]);$remaining=(int)g('SELECT COUNT(*) FROM iv_order_lines WHERE tenant_id=? AND order_id=? AND received<quantity',[$tid,$o['id']]);q('UPDATE iv_orders SET status=? WHERE tenant_id=? AND id=?',[$remaining?'partial':'received',$tid,$o['id']]);fnJournal($tid,'PO-RCV-'.$receipt,'1200','2000',$qty*(int)$line['unit_kobo'],'','Goods received PO #'.$o['id']);return 'Goods received once; inventory and supplier payable journal updated.';});}
 if($a==='pay_order'){if($u['role']!=='school_admin')throw new RuntimeException('School administrator required to confirm external payment.');return sv_tx(function()use($u,$tid){$o=sv_own('iv_orders',$u,op_id('order_id'),true);if($o['status']!=='received'||$o['payment_ref'])throw new RuntimeException('Only a fully received unpaid order can be confirmed.');$amount=(int)g('SELECT SUM(quantity*unit_kobo) FROM iv_order_lines WHERE tenant_id=? AND order_id=?',[$tid,$o['id']]);$ref=op_text('payment_ref',120,true);fnJournal($tid,'PO-PAY-'.$o['id'],'2000','1000',$amount,'','Manual supplier payment '.$ref);q("UPDATE iv_orders SET status='paid',payment_ref=? WHERE tenant_id=? AND id=?",[$ref,$tid,$o['id']]);return 'Manual supplier payment recorded once; no bank transfer initiated.';});}
 if($a==='store_approve'||$a==='store_fulfill'){return sv_tx(function()use($u,$tid,$uid,$a){$o=sv_own('iv_store_orders',$u,op_id('order_id'),true);if($a==='store_approve'){if($o['status']!=='requested')throw new RuntimeException('Store request is already handled.');$item=sv_own('inventory',$u,(int)$o['item_id'],true);$inv=sv_invoice($u,(int)$o['student_id'],'STORE-'.$o['id'],(int)$o['quantity']*(int)$o['unit_kobo'],'School store: '.$item['name']);iv_move($u,$item,-(int)$o['quantity'],'store_reserve','Student #'.$o['student_id'],'Reserved pending Finance payment','STORE-'.$o['id']);q("UPDATE iv_store_orders SET status='awaiting_payment',invoice_id=?,handled_by=? WHERE tenant_id=? AND id=?",[$inv,$uid,$tid,$o['id']]);return 'Stock reserved and Finance invoice generated. Family pays through existing Finance.';}if($o['status']!=='awaiting_payment')throw new RuntimeException('Order is not awaiting payment.');$i=sv_own('fn_invoices',$u,(int)$o['invoice_id'],true);if($i['status']!=='paid')throw new RuntimeException('Finance must confirm full payment before handover.');q("UPDATE iv_store_orders SET status='fulfilled',handled_by=? WHERE tenant_id=? AND id=?",[$uid,$tid,$o['id']]);return 'Paid order handed over once. Stock was reserved at approval.';});}
 if($a==='audit'){return sv_tx(function()use($u,$tid,$uid){$i=sv_own('inventory',$u,op_id('item_id'),true);q('INSERT INTO iv_audits(tenant_id,item_id,expected,observed,note,created_by) VALUES(?,?,?,?,?,?)',[$tid,$i['id'],$i['quantity'],sv_qty('observed',100000000,true),op_text('note',2000,true),$uid]);return 'Physical count captured against a locked stock snapshot. Any correction needs a separate referenced adjustment.';});}
 throw new RuntimeException('Unsupported inventory action.');
}
function iv_render(array $u):void{
 $tid=(int)$u['tenant_id'];$stock=sv_can($u,'stock_manager');$approver=sv_can($u,'procurement_approver');$asset=sv_can($u,'asset_manager');$employee=in_array($u['role'],['staff','teacher','school_admin'],true);$tabs=['store'=>'School store','orders'=>'My store orders'];if($employee)$tabs['requests']='Purchase requests';if($stock||$approver)$tabs+=['stock'=>'Stock & issuance','suppliers'=>'Suppliers','purchases'=>'Purchase orders','alerts'=>'Low-stock alerts','audits'=>'Stock audits'];if($asset)$tabs+=['assets'=>'Asset register','depreciation'=>'Depreciation','maintenance'=>'Maintenance & asset audits'];$view=sv_tabs('inventory',$tabs,'store');op_card($tabs[$view]);
 $items=q('SELECT i.*,m.kind,m.price_kobo,m.cost_kobo,m.store_active FROM inventory i LEFT JOIN iv_items m ON m.item_id=i.id AND m.tenant_id=i.tenant_id WHERE i.tenant_id=? ORDER BY i.name LIMIT 1000',[$tid])->fetchAll();$ic=op_choices($items);$ef=['item_id'=>['Stock item',$ic]];
 if($view==='store'){
  $store=array_values(array_filter($items,fn($i)=>$i['store_active']&&(int)$i['price_kobo']>0));op_table(array_map(fn($i)=>[$i['id'],$i['name'],$i['kind'],$i['quantity'],op_fmt((int)$i['price_kobo'])],$store),['ID','Item','Type','Available stock','Price']);$sc=$stock?op_choices(q('SELECT id,name FROM students WHERE tenant_id=? ORDER BY name',[$tid])->fetchAll()):sv_children($u);if($sc)sv_form('iv_store_request',['student_id'=>['Student',$sc],'item_id'=>['Uniform, book or store item',op_choices($store)],'quantity'=>['Quantity','number','1']],'Request school-store order');else echo '<p>Store orders require a linked child or stock manager.</p>';
 }elseif($view==='orders'){
  $rows=q('SELECT o.id,s.name,i.name item,o.quantity,o.unit_kobo,o.status,o.invoice_id FROM iv_store_orders o JOIN students s ON s.id=o.student_id AND s.tenant_id=o.tenant_id JOIN inventory i ON i.id=o.item_id AND i.tenant_id=o.tenant_id WHERE o.tenant_id=?'.($stock?'':' AND o.requested_by=?').' ORDER BY o.id DESC LIMIT 200',$stock?[$tid]:[$tid,$u['id']])->fetchAll();op_table(array_map(fn($r)=>[$r['id'],$r['name'],$r['item'],$r['quantity'],op_fmt((int)$r['unit_kobo']),$r['status'],$r['invoice_id']],$rows),['Order','Student','Item','Quantity','Unit price','Status','Finance invoice']);sv_form('iv_store_cancel',['order_id'=>['Unapproved order ID','number']],'Cancel unapproved request');if($stock){sv_form('iv_store_approve',['order_id'=>['Requested order ID','number']],'Reserve stock & create invoice');sv_form('iv_store_fulfill',['order_id'=>['Paid order ID','number']],'Record paid handover');}echo '<p>Approved orders reserve stock and create a Finance invoice. Payment and receipts use existing Finance / Family Space. Invoiced cancellations/refunds require Finance review; stock is not silently released.</p>';
 }elseif($view==='requests'){
  $rows=q('SELECT r.id,i.name,r.quantity,r.unit_kobo,r.reason,r.status,r.requested_by FROM iv_requests r JOIN inventory i ON i.id=r.item_id AND i.tenant_id=r.tenant_id WHERE r.tenant_id=?'.($stock||$approver?'':' AND r.requested_by=?').' ORDER BY r.id DESC LIMIT 200',$stock||$approver?[$tid]:[$tid,$u['id']])->fetchAll();op_table($rows,['ID','Item','Quantity','Unit kobo','Reason','Status','Requester']);sv_form('iv_request',$ef+['quantity'=>['Quantity','number'],'unit_cost'=>['Quoted unit cost (NGN)','text'],'reason'=>['Purchase justification','textarea']],'Submit purchase request');if($approver)sv_form('iv_review_request',['request_id'=>['Request ID','number'],'status'=>['Decision',['approved'=>'Approve independently','rejected'=>'Reject']]],'Review request');
