  if(!$stock&&!$approver)throw new RuntimeException('Stock access required.');$rows=$view==='alerts'?array_filter($items,fn($i)=>(int)$i['quantity']<=(int)$i['reorder_level']):$items;op_table(array_map(fn($i)=>[$i['id'],$i['name'],$i['category'],$i['quantity'],$i['reorder_level'],op_fmt((int)($i['cost_kobo']??0))],array_values($rows)),['ID','Item','Category','Quantity','Reorder at','Unit carrying cost']);
  if($stock&&$view==='stock'){
   sv_form('iv_item',['item_id'=>['Item ID (0 to create)','number','0'],'name'=>['Item name','text'],'category'=>['Category / size / edition','text'],'kind'=>['Type',['uniform'=>'Uniform','book'=>'Book for sale','store'=>'School store','consumable'=>'Consumable']],'reorder_level'=>['Reorder level','number','5'],'price'=>['Store price (NGN)','text','0'],'cost'=>['Opening unit cost (new setup only, NGN)','text','0'],'store_active'=>['Offer through school store','check']],'Save stock configuration');sv_form('iv_adjust',$ef+['delta'=>['Whole units received (+) / corrected (-)','number'],'recipient'=>['Custodian / location','text'],'reference'=>['Unique movement reference','text'],'note'=>['Reason / opening stock source','textarea']],'Record stock adjustment');sv_form('iv_issue',$ef+['quantity'=>['Whole units issued','number'],'recipient'=>['Staff / department / student recipient','text'],'reference'=>['Unique issue reference','text'],'note'=>['Purpose','textarea']],'Issue stock');op_table(q('SELECT item_id,delta,kind,recipient,note,event_key,created_at FROM iv_moves WHERE tenant_id=? ORDER BY id DESC LIMIT 200',[$tid])->fetchAll(),['Item','Units','Kind','Recipient','Note','Reference','Recorded']);
  }if($view==='audits'){op_table(q('SELECT item_id,expected,observed,(observed-expected) variance,note,created_at FROM iv_audits WHERE tenant_id=? ORDER BY id DESC LIMIT 100',[$tid])->fetchAll(),['Item','Expected','Observed','Variance','Note','Counted']);if($stock)sv_form('iv_audit',$ef+['observed'=>['Physical count','number'],'note'=>['Audit details / witness','textarea']],'Capture physical stock audit');}
 }elseif($view==='suppliers'){
  op_table(q('SELECT id,name,email,phone,address FROM iv_suppliers WHERE tenant_id=?',[$tid])->fetchAll(),['ID','Supplier','Email','Phone','Address']);if($stock)sv_form('iv_supplier',['name'=>['Supplier name','text'],'email'=>['Email','email','',false],'phone'=>['Phone','tel'],'address'=>['Address','textarea']],'Register supplier');
 }elseif($view==='purchases'){
  $orders=q('SELECT o.id,s.name,o.status,o.created_by,o.approved_by,o.payment_ref FROM iv_orders o JOIN iv_suppliers s ON s.id=o.supplier_id AND s.tenant_id=o.tenant_id WHERE o.tenant_id=? ORDER BY o.id DESC',[$tid])->fetchAll();op_table($orders,['PO','Supplier','Status','Created by','Approved by','Payment ref']);op_table(q('SELECT l.id,l.order_id,l.request_id,i.name,l.quantity,l.unit_kobo,l.received FROM iv_order_lines l JOIN inventory i ON i.id=l.item_id AND i.tenant_id=l.tenant_id WHERE l.tenant_id=? ORDER BY l.id DESC LIMIT 200',[$tid])->fetchAll(),['Line ID','PO','Request','Item','Ordered','Unit kobo','Received']);
  if($stock){sv_form('iv_order',['supplier_id'=>['Supplier',op_choices(q('SELECT id,name FROM iv_suppliers WHERE tenant_id=? AND active=1',[$tid])->fetchAll())]],'Create draft order');sv_form('iv_order_line',['order_id'=>['Draft PO ID','number'],'request_id'=>['Approved request ID','number']],'Add approved request');sv_form('iv_submit_order',['order_id'=>['Draft PO ID','number']],'Submit order');sv_form('iv_receive',['line_id'=>['Approved order line ID','number'],'quantity'=>['Quantity received','number'],'reference'=>['Unique supplier delivery / receipt reference','text']],'Receive goods');if($u['role']==='school_admin')sv_form('iv_pay_order',['order_id'=>['Fully received PO ID','number'],'payment_ref'=>['Actual external supplier payment reference','text']],'Confirm manual supplier payment');}if($approver)sv_form('iv_approve_order',['order_id'=>['Submitted PO ID','number']],'Approve as independent reviewer');echo '<p>Partial receipts are supported. Receipt references prevent duplicate stock and supplier payable entries. Manual payment confirmation posts once and does not transfer money.</p>';
 }else{
