  elseif($view==='depreciation'){sv_form('iv_depreciate',['asset_id'=>['Asset',$ac],'period'=>['Period through which to post','month']],'Post cumulative straight-line depreciation');echo '<p>Includes acquisition month, rounds cumulative depreciation down to whole kobo, and never reduces value below residual. No future or duplicate/earlier period posting. Acquisition setup does not create a payment or opening-balance entry.</p>';}
  else{sv_form('iv_asset_event',['asset_id'=>['Asset',$ac],'kind'=>['Record',['maintenance'=>'Maintenance','audit'=>'Physical asset audit']],'title'=>['Title','text'],'body'=>['Findings, condition, location, custodian and follow-up','textarea']],'Record asset event');sv_form('iv_close_asset_event',['event_id'=>['Event ID','number']],'Close maintenance / audit');}op_table(q('SELECT id,asset_id,kind,title,body,status,amount_kobo,period FROM iv_asset_events WHERE tenant_id=? ORDER BY id DESC LIMIT 150',[$tid])->fetchAll(),['ID','Asset','Kind','Title','Details','Status','Kobo','Period']);
 }
 echo '</section>';
